// levelClass returns a CSS class name based on the sensor's name and value:
//
//	level-good (green) / level-ok (yellow) / level-warn (orange) / level-bad (red)
//
// Empty string means no color band.
func levelClass(s state.Sensor) string {
	f, err := strconv.ParseFloat(s.Value, 64)
	if err != nil {
		return ""
	}
	switch strings.ToLower(s.Name) {
	case "temperature":
		return TempLevelClass(f)
	case "air quality":
		// US AQI scale (lower is better).
		switch {
		case f <= 50:
			return "level-good"
		case f <= 100:
			return "level-ok"
		case f <= 150:
			return "level-warn"
		default:
			return "level-bad"
		}
	case "humidity":
		// Indoor comfort: 30-60% ideal; 20-30 or 60-70 ok; outside that warn.
		switch {
		case f >= 30 && f <= 60:
			return "level-good"
		case f >= 20 && f <= 70:
			return "level-ok"
		case f >= 15 && f <= 75:
			return "level-warn"
		default:
			return "level-bad"
		}
	case "pressure":
		// Sea-level normal ~1013 hPa. Tight band = normal, wider = caution.
		switch {
		case f >= 1005 && f <= 1025:
			return "level-good"
		case f >= 995 && f <= 1035:
			return "level-ok"
		default:
			return "level-warn"
		}
	}
	return ""
}

// TempLevelClass returns a temperature-band CSS class. Bands are tuned for
// indoor + outdoor air in degrees Celsius and reused by the weather widget
