func TempLevelClass(c float64) string {
	switch {
	case c < 10:
		return "level-cold"
	case c < 15:
		return "level-chill"
	case c < 20:
		return "level-cool"
	case c < 24:
		return "level-perfect"
	case c < 28:
		return "level-warmish"
	case c < 35:
		return "level-hot"
	default:
		return "level-boiling"
	}
}

